  // ---------------------------------------------------------------- mesh engine
  await T('mesh engine', () => {
    const s = M.meshStats(cube);
    near(s.volume, 24, 1e-12, 'cube volume'); near(s.surfaceArea, 52, 1e-12, 'cube area'); ok(s.watertight && s.consistentNormals && s.outwardNormals, 'cube watertight with outward normals');
    ok(s.eulerCharacteristic === 2 && s.genus === 0 && s.boundaryEdges === 0 && s.nonManifoldEdges === 0 && s.duplicateVertices === 0 && s.degenerateFaces === 0, 'cube topology (χ = 2, genus 0, no defects)');
    for (const [n, m, v, g] of [['cylinder', M.cylinder({ radius: 1, height: 2, segments: 96 }), 2 * Math.PI, 0], ['sphere', M.sphere({ radius: 1, segments: 64 }), 4 / 3 * Math.PI, 0], ['cone', M.cone({ r1: 1, r2: 0, height: 3, segments: 96 }), Math.PI, 0], ['tube', M.tube({ outer: 2, inner: 1, height: 1, segments: 96 }), 3 * Math.PI, 1], ['torus', M.torus({ R: 3, r: 1, segments: 96, tubeSegments: 48 }), 2 * Math.PI ** 2 * 3, 1], ['hexPrism', M.hexPrism({ acrossFlats: 2, height: 1 }), 2 * Math.sqrt(3), 0]]) { const q = M.meshStats(m); near(q.volume, v, 0.01, `${n} volume`); ok(q.watertight && q.consistentNormals && q.genus === g, `${n} watertight, genus ${g} (got ${q.genus})`); }
    const pl = M.meshStats(M.plateWithHoles({ size: [40, 40], thickness: 2, holes: { nx: 4, ny: 4, diameter: 5, segments: 32 } })); ok(pl.watertight && pl.genus === 16, `plate with 16 holes: genus ${pl.genus}`); near(pl.volume, 2 * (1600 - 16 * Math.PI * 6.25), 0.01, 'plate volume');
    const soup = { kind: 'mesh', units: 'mm', vertices: cube.faces.flatMap(f => f.map(i => [...cube.vertices[i]])), faces: cube.faces.map((f, i) => i % 3 ? [3 * i, 3 * i + 1, 3 * i + 2] : [3 * i, 3 * i + 2, 3 * i + 1]) };
    soup.faces.push([0, 0, 1]); const b = M.meshStats(soup); ok(!b.watertight && b.duplicateVertices > 0 && b.degenerateFaces === 1, 'defective mesh is diagnosed');
    const r = M.repairMesh(soup), a = r.stats; ok(a.watertight && a.consistentNormals && a.nVertices === 8 && a.nFaces === 12, 'repair welds, removes degenerate faces and fixes winding'); near(a.volume, 24, 1e-9, 'repaired volume'); ok(r.report.length >= 3, 'repair report lists every change');
    const t = M.meshStats(M.transformMesh(cube, { scale: [2, 1, 1], rotate: [30, 40, 50], translate: [5, 6, 7] })); near(t.volume, 48, 1e-9, 'transform preserves scaled volume'); near(M.meshStats(M.transformMesh(cube, { scale: [-1, 1, 1] })).volume, 24, 1e-9, 'mirror keeps outward orientation');
    for (const type of ['autoclave', 'tubular', 'cstr', 'porousSlab', 'cvdTube', 'electrochemCell']) { const re = M.reactor({ type }), q = M.meshStats(re.mesh); ok(q.watertight && q.consistentNormals && q.volume > 0, `reactor ${type}: closed shells`); ok(re.volume_m3 > 0 && re.wettedArea_m2 > 0 && re.regions.some(g => g.role === 'fluid') && re.regions.every(g => Number.isFinite(g.volume_m3) && Number.isFinite(g.area_m2)), `reactor ${type}: regions and fluid volume`); }
    near(M.reactor({ type: 'autoclave', dims: { innerDiameter: 30, innerHeight: 50, fill: 0.7 }, features: { substrate: false } }).volume_m3, Math.PI * 15 * 15 * 35 * 1e-9, 1e-9, 'autoclave liquid volume = π r² h · fill');
    const rods = M.nanorodArray({ density_per_um2: 50, area_nm: [1000, 1000], seed: 3 }); ok(rods.kind === 'rods' && rods.rods.length === 50, `nanorod count = density × area (${rods.rods.length})`); ok(JSON.stringify(M.nanorodArray({ seed: 3 }).rods) === JSON.stringify(M.nanorodArray({ seed: 3 }).rods), 'nanorod array is deterministic for a seed');
    const rm = M.meshStats(M.rodsToMesh(rods)); ok(rm.watertight && rm.components === 50, 'rods → 50 closed hexagonal prisms');
    const w = 64, h = 48, img = new Uint8Array(w * h); for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) img[x + w * y] = ((x - 20) ** 2 + (y - 20) ** 2 < 64 || ((x - 45) / 10) ** 2 + ((y - 30) / 5) ** 2 < 1) ? 200 : 30;
    const pr = M.segmentParticles(img, w, h); ok(pr.length === 2, 'two particles segmented'); near(pr[0].equivDiameter_px, 16, 0.05, 'disc equivalent diameter'); near(pr[1].aspect, 2, 0.1, 'ellipse aspect ratio'); ok(M.otsu(img) >= 30 && M.otsu(img) < 200, 'Otsu threshold between the two grey levels');
    const vi = M.voxelsFromImage({ width: w, height: h, data: img }, { depth: 3, pixelSize: 2, units: 'nm' }); ok(vi.kind === 'voxels' && vi.nz === 3 && vi.data.length === w * h * 3, 'image → voxels extruded'); near(vi.phaseFraction, pr.reduce((s, p) => s + p.area_px, 0) / (w * h), 1e-9, 'phase fraction equals particle area fraction');
    const rgba = new Uint8ClampedArray(w * h * 4); for (let i = 0; i < w * h; i++) { rgba[4 * i] = rgba[4 * i + 1] = rgba[4 * i + 2] = img[i]; rgba[4 * i + 3] = 255; } near(M.voxelsFromImage({ width: w, height: h, data: rgba }).phaseFraction, vi.phaseFraction, 1e-9, 'RGBA input gives the same segmentation');
  });

