    const m3 = F.unzip(F.to3MF(cube)).map(q => q.name); ok(m3.includes('[Content_Types].xml') && m3.includes('_rels/.rels') && m3.includes('3D/3dmodel.model'), '3MF is an OPC package with the three required parts');
